SELECT FROM posts p JOIN users u ON u.id = p.user_id AND u.deleted_at IS NULL WHERE AND p.user_id = #{userId}
AND (p.created_at, p.id) < (#{cursorCreatedAt}, #{cursorId})
ORDER BY p.created_at DESC, p.id DESC LIMIT #{limit}

SELECT COUNT(*)
FROM posts p
WHERE 

  AND ( p.user_id = #{meId}
     OR p.user_id IN (SELECT f.followee_id FROM follows f WHERE f.follower_id = #{meId}) )

  AND p.id > #{sinceId}
